const ahoraARG = new Date(
  new Date().toLocaleString("en-US", { timeZone: "America/Argentina/Buenos_Aires" })
);

const hora = ahoraARG.getHours() + ahoraARG.getMinutes() / 60;
const diaSemana = ahoraARG.getDay(); // 0=Dom, 1=Lun, ..., 5=Vie, 6=Sab

let diasASumar;
if (diaSemana === 0) {
  // Domingo → siempre lunes
  diasASumar = 1;
} else if (diaSemana === 6) {
  // Sábado: antes de las 12hs → hoy, después → lunes
  diasASumar = hora < 12 ? 0 : 2;
} else {
  // Lunes a Viernes: antes de las 15hs → hoy, después → mañana (viernes → lunes)
  if (hora < 15) {
    diasASumar = 0;
  } else {
    diasASumar = diaSemana === 5 ? 3 : 1;
  }
}

// -------- 3) Generar próximos 5 días válidos --------
const salida = [];
let cur = new Date(ahoraARG.getFullYear(), ahoraARG.getMonth(), ahoraARG.getDate() + diasASumar);

while (salida.length < 5) {
  const iso = formatISOFromLocal(cur);
  const esDomingo = cur.getDay() === 0;
  const estaBloqueada = bloqueadasISO.has(iso);

  if (!esDomingo && !estaBloqueada) {
    salida.push({ json: { fecha_valida: formatDDMMYYYY(cur), fecha_iso: iso } });
  }

  cur.setDate(cur.getDate() + 1);
}

return salida;

